    var hi=x.evn==='mkt'?(m.hi||[]).filter(function(v,i,ar){return v%1===0&&v>=0&&v<x.hand[seat].length&&ar.indexOf(v)===i;}):[];
    var cards=fi.map(function(i2){return x.fu[i2];}).concat(hi.map(function(i2){return x.hand[seat][i2];}));
    var hat=m.t===-2,tt=hat?-2:(m.t%1===0&&m.t>=0&&m.t<JZ.length?m.t:-1),jj=hat?1:(tt<0?0:Math.max(1,Math.min(2,m.j|0||1)));
    if(!cards.length||cards.length>(hat?2:4))return false;
